//! 🧫️ Actual source callers, native decoder receipts and heap witnesses exercise same-allocation factory admission.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,RevisionId,InteractiveJobCloseStep,JobOutcomeBorrow,JobOutcomeDescriptor,JobOutcomeView};
struct Job{identity:Option<OriginalToolJobIdentity>,body:[u8;70000]}
impl InteractiveJob for Job{
 fn step<'a>(&'a mut self,_:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,OriginalTurnFailure>{Ok(None)}
 fn borrow_outcome<'a>(&'a self,_:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"fixture has no publication"))}
 fn begin_close(&mut self){}
 fn close_step(&mut self,_:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}
 fn terminal_is_empty(&self)->bool{true}
}
pub(crate) fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:64}}
pub(crate) fn clock()->Option<u64>{Some(1)}
pub(crate) fn source<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,value:T)->Box<T>{
 let mut slot=None;caller.turn_with_decoder(grant(),decoder,|cx|{let result=cx.with_native_receiving::<_,semio_framework_value_native_owned::native_decoding::NativeConstructionStepFailure<ValueError>>(|control|control.receive_construction_step(RetirementDemand{capacity_bytes:size_of::<T>(),depth:1,..Default::default()},|control,_|{control.charge(size_of::<T>())?;slot=Some(Box::new(value));Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,retained_capacity_bytes:size_of::<T>(),..Default::default()}))}));let progress=match &result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};let reconciled=cx.consume_receiving_retained(cx.receiving_issued_grant().unwrap(),progress);cx.consume_fuel(progress.copied_items as u64);match(result,reconciled){(Ok(_),Ok(()))=>Ok(()),(Err(error),Ok(()))=>Err(error.into()),(Ok(_),Err(error))=>Err(error.into()),(Err(error),Err(receipt))=>{let mut failure=semio_framework_job::OriginalTurnFailure::from(error);failure.context_refusal=Some(receipt);Err(failure)}}}).unwrap();slot.unwrap()
}
fn release<T>(caller:&mut OriginalJobFixtureCaller,slot:&mut Option<Box<T>>){if slot.is_some(){caller.turn(grant(),|cx|{drop(slot.take());cx.consume_retained(RetainedCloneProgress{copied_items:1,released_bytes:size_of::<T>(),..Default::default()})?;cx.consume_fuel(1);Ok(())}).unwrap();}}
pub(crate) fn close(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){while !decoder.terminal_is_empty(){caller.turn(grant(),|cx|{let step=decoder.close_step(cx.retained_grant())?;cx.consume_retained(step.progress())?;cx.consume_fuel(step.progress().copied_items as u64);Ok(())}).unwrap();}}
#[test]
fn actual_original_factory_denied_axes_keep_same_box_and_admitted_reuse_has_zero_heap_effects(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for case in corpus["cases"].as_array().unwrap(){let operation=Operation::new(OperationId(case["operation"].as_u64().unwrap()),RevisionId(0),Generation(case["generation"].as_u64().unwrap()),0);let mut caller=OriginalJobFixtureCaller::admit(operation.operation,operation.generation,grant(),clock,u64::MAX,10000);let mut decoder=OriginalJobDecodeOwner::empty();let mut payload=Some(source(&mut caller,&mut decoder,Job{identity:None,body:[7;70000]}));let original=payload.as_deref().unwrap() as *const Job;let mut input=None;let mut checkpoint=None;let mut output=None;
 for axis in 0..2{let denied=if axis==0{RetainedCloneGrant{maximum_items:0,..grant()}}else{RetainedCloneGrant{maximum_depth:0,..grant()}};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(denied,&mut decoder,|cx|admit_original_tool_job(cx,&operation,&mut payload,&mut input,&mut checkpoint,&mut output,ToolJobAdmissionDemand::reused_job(),|identity,mut job,_,_|{job.identity=Some(identity);job})));assert!(!result.unwrap());assert_eq!(heap.requested_bytes,0);assert_eq!(heap.released_bytes,0);assert_eq!(payload.as_deref().unwrap()as*const Job,original);assert!(output.is_none());}
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant(),&mut decoder,|cx|admit_original_tool_job(cx,&operation,&mut payload,&mut input,&mut checkpoint,&mut output,ToolJobAdmissionDemand::reused_job(),|identity,mut job,_,_|{job.identity=Some(identity);job})));assert!(result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(output.as_deref().unwrap()as*const Job,original);let identity=output.as_deref().unwrap().identity.unwrap();assert_eq!((identity.operation(),identity.generation()),(operation.operation,operation.generation));assert_eq!(output.as_deref().unwrap().body[69999],7);assert_eq!(caller.receipt(),RetainedCloneProgress{copied_items:1,..Default::default()});release(&mut caller,&mut output);close(&mut caller,&mut decoder);caller.retire(grant());}
 eprintln!("[DEBUG] original factory same Box, denied physical axes, original operation/generation and zero heap transfer verified");
}
#[test]
fn actual_original_factory_post_birth_cancellation_retains_candidate_and_whole_physical_receipt(){
 let operation=Operation::new(OperationId(93),RevisionId(0),Generation(11),0);let mut caller=OriginalJobFixtureCaller::admit(operation.operation,operation.generation,grant(),clock,u64::MAX,10000);let cancel=caller.admit_alias(grant());let mut decoder=OriginalJobDecodeOwner::empty();let mut payload=Some(source(&mut caller,&mut decoder,9u64));let mut input=None;let mut checkpoint=None;let mut output=None;let demand=ToolJobAdmissionDemand::boxed_job::<u64,Job>();
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant(),&mut decoder,|cx|admit_original_tool_job(cx,&operation,&mut payload,&mut input,&mut checkpoint,&mut output,demand,|identity,payload,_,_|{let job=Box::new(Job{identity:Some(identity),body:[*payload as u8;70000]});drop(payload);cancel.cancel_now();job})));let failure=result.unwrap_err();assert_eq!(failure.primary_receiving().unwrap().allocation_refusal.as_ref().unwrap().kind,ValueRefusalKind::Canceled);assert_eq!(failure.primary.retained_progress(),demand.progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(demand.capacity_bytes,demand.release_bytes));assert!(payload.is_none());assert_eq!(output.as_deref().unwrap().body[69999],9);assert_eq!(caller.receipt(),demand.progress());assert_eq!(decoder.owned_bytes(),size_of::<u64>()+size_of::<Job>());release(&mut caller,&mut output);close(&mut caller,&mut decoder);caller.return_alias(cancel,grant());caller.retire(grant());eprintln!("[DEBUG] born candidate and actual physical receipt survive original cancellation refusal before decoder charge acceptance");
}

#[test]
fn actual_constructor_primary_and_physical_receipt_survive_secondary_original_cancellation(){
 let operation=Operation::new(OperationId(107),RevisionId(0),Generation(37),0);let mut caller=OriginalJobFixtureCaller::admit(operation.operation,operation.generation,grant(),clock,u64::MAX,10000);let cancel=caller.admit_alias(grant());let mut decoder=OriginalJobDecodeOwner::empty();let mut payload=Some(source(&mut caller,&mut decoder,13u64));let pointer=payload.as_deref().unwrap()as*const u64;let mut input=None;let mut checkpoint=None;let mut output:Option<Box<Job>>=None;let demand=ToolJobAdmissionDemand{items:1,copy_bytes:0,capacity_bytes:70000,release_bytes:70000,depth:1};let progress=RetainedCloneProgress{copied_items:1,retained_capacity_bytes:70000,released_bytes:70000,..Default::default()};
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant(),&mut decoder,|cx|admit_original_tool_job_controlled(cx,&operation,&mut payload,&mut input,&mut checkpoint,&mut output,demand,|_,_,_,_|{let temporary=Vec::<u8>::with_capacity(70000);assert_eq!(temporary.capacity(),70000);drop(temporary);cancel.cancel_now();Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original constructor refusal retained whole").with_retained_progress(progress))})));let failure=result.unwrap_err();assert_eq!(failure.primary_receiving().unwrap().primary.as_ref().unwrap().kind,ValueRefusalKind::InvalidValue);assert_eq!(failure.primary.retained_progress(),progress);assert_eq!(failure.primary_receiving().unwrap().allocation_refusal.as_ref().unwrap().kind,ValueRefusalKind::Canceled);assert_eq!((heap.requested_bytes,heap.released_bytes),(70000,70000));assert_eq!(decoder.owned_bytes(),size_of::<u64>()+70000);assert_eq!(caller.receipt(),progress);assert_eq!(payload.as_deref().unwrap()as*const u64,pointer);assert!(output.is_none());release(&mut caller,&mut payload);close(&mut caller,&mut decoder);caller.return_alias(cancel,grant());caller.retire(grant());eprintln!("[DEBUG] whole primary constructor refusal, original source Box, actual temporary effects and secondary native cancellation remain distinct");
}

#[test]
fn scoped_nested_owner_refusal_is_atomic_and_allocator_over_quote_keeps_actual_decoder_truth(){
 let operation=Operation::new(OperationId(109),RevisionId(0),Generation(41),0);let mut caller=OriginalJobFixtureCaller::admit(operation.operation,operation.generation,grant(),clock,u64::MAX,10000);let mut decoder=OriginalJobDecodeOwner::empty();let mut output:Option<Box<[u8;70000]>>=None;
 let demand=ToolJobAdmissionDemand{items:1,copy_bytes:0,capacity_bytes:69999,release_bytes:0,depth:1};let actual=RetainedCloneProgress{copied_items:1,retained_capacity_bytes:70000,..Default::default()};
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant(),&mut decoder,|cx|admit_original_tool_construction_scoped(cx,&mut output,demand,|scope|{assert!(scope.admit_owner(RetirementDemand{capacity_bytes:70000,depth:1,..Default::default()}).is_err());scope.admit_owner(RetirementDemand{capacity_bytes:69999,depth:1,..Default::default()})?;assert!(scope.admit_owner(RetirementDemand{capacity_bytes:1,depth:1,..Default::default()}).is_err());Ok((Box::new([3;70000]),actual))})));
 let failure=result.unwrap_err();assert_eq!(failure.primary_receiving().unwrap().quote_refusal.as_ref().unwrap().kind,ValueRefusalKind::InvariantViolated);assert_eq!(failure.primary.retained_progress(),actual);assert_eq!(decoder.owned_bytes(),70000);assert_eq!(heap.requested_bytes,70000);assert_eq!(output.as_deref().unwrap()[69999],3);assert_eq!(caller.receipt(),actual);release(&mut caller,&mut output);close(&mut caller,&mut decoder);caller.retire(grant());eprintln!("[DEBUG] nested quote refusal leaves remaining budget intact and actual over-quote allocation survives in caller candidate and original decoder ledger");
}

#[test]
fn original_scoped_nested_owner_admission_matches_every_neutral_quote(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🧰️scope/🔣️.json")).unwrap();let operation=Operation::new(OperationId(113),RevisionId(0),Generation(43),0);let mut caller=OriginalJobFixtureCaller::admit(operation.operation,operation.generation,grant(),clock,u64::MAX,10000);let mut decoder=OriginalJobDecodeOwner::empty();
 for row in corpus["cases"].as_array().unwrap(){let numbers=|key:&str|->[usize;4]{std::array::from_fn(|axis|row[key][axis].as_u64().unwrap()as usize)};let quote=numbers("quote");let mut output=None;let admitted=caller.turn_with_decoder(grant(),&mut decoder,|cx|admit_original_tool_construction_scoped(cx,&mut output,ToolJobAdmissionDemand{items:1,copy_bytes:quote[0],capacity_bytes:quote[1],release_bytes:quote[2],depth:quote[3]},|scope|{for(index,owner)in row["owners"].as_array().unwrap().iter().enumerate(){let value=|axis:usize|owner[axis].as_u64().unwrap()as usize;let result=scope.admit_owner(RetirementDemand{copy_bytes:value(0),capacity_bytes:value(1),release_bytes:value(2),depth:value(3)});assert_eq!(result.is_ok(),row["accepted"][index].as_bool().unwrap());}let remaining=numbers("remaining");assert_eq!([scope.remaining.copy_bytes,scope.remaining.capacity_bytes,scope.remaining.release_bytes,scope.remaining.depth],remaining);Ok(((),RetainedCloneProgress{copied_items:1,..Default::default()}))})).unwrap();assert!(admitted&&output.is_some());assert_eq!(decoder.owned_bytes(),0);}
 close(&mut caller,&mut decoder);caller.retire(grant());eprintln!("[DEBUG] real original construction scopes enforce all neutral owner reservations without fabricated physical receipts");
}

#[test]
fn actual_original_close_denials_preserve_each_cursor_and_exact_physical_receipt(){
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(107),Generation(13),grant(),clock,u64::MAX,100000);let mut decoder=OriginalJobDecodeOwner::empty();let mut output=None;
 caller.turn_with_decoder(grant(),&mut decoder,|cx|admit_original_tool_construction(cx,&mut output,ToolJobAdmissionDemand{capacity_bytes:128,..ToolJobAdmissionDemand::reused_job()},|_|{let mut bytes=Vec::<u8>::with_capacity(128);bytes.extend_from_slice(&[7;128]);let actual=bytes.capacity();let owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(bytes).map_err(|(error,_)|error)?;Ok((owner,RetainedCloneProgress{copied_items:1,retained_capacity_bytes:actual,..Default::default()}))})).unwrap();
 let owner=output.as_mut().unwrap();for _ in 0..10000{if owner.terminal_is_empty(){break}let demand=owner.next_demand(grant().maximum_copy_bytes).unwrap();let funded=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};
 for axis in 0..5{let mut denied=funded;let extent=match axis{0=>&mut denied.maximum_items,1=>&mut denied.maximum_copy_bytes,2=>&mut denied.maximum_capacity_bytes,3=>&mut denied.maximum_release_bytes,_=>&mut denied.maximum_depth};if *extent==0{continue}*extent-=1;let before=caller.cumulative_receipt();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(denied,|cx|semio_framework_job::close_original_retained_step(cx,demand,|loan|owner.step(loan))));assert_eq!(result.unwrap().progress(),Default::default());assert_eq!(heap,Default::default());assert_eq!(caller.cumulative_receipt(),before);}
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(funded,|cx|semio_framework_job::close_original_retained_step(cx,demand,|loan|owner.step(loan))));let receipt=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(caller.receipt(),receipt);
 }assert!(owner.terminal_is_empty());output.take();close(&mut caller,&mut decoder);caller.retire(grant());eprintln!("[DEBUG] authentic original close denies each currency without heap effects and records every real cursor birth and release");
}
#[test]
fn actual_original_close_failure_keeps_whole_primary_and_actual_released_backing(){
 for diagnostic in [false,true]{let mut caller=OriginalJobFixtureCaller::admit(OperationId(108),Generation(13),grant(),clock,u64::MAX,10000);let mut decoder=OriginalJobDecodeOwner::empty();let mut original=None;
 caller.turn_with_decoder(grant(),&mut decoder,|cx|admit_original_tool_construction(cx,&mut original,ToolJobAdmissionDemand{capacity_bytes:128,..ToolJobAdmissionDemand::reused_job()},|_|{let bytes=Vec::<u8>::with_capacity(128);let actual=bytes.capacity();Ok((bytes,RetainedCloneProgress{copied_items:1,retained_capacity_bytes:actual,..Default::default()}))})).unwrap();let released=original.as_ref().unwrap().capacity();let receipt=RetainedCloneProgress{copied_items:1,released_bytes:released,..Default::default()};
 let mut primary=Some(if diagnostic{let mut fault=semio_framework_diagnostic::Fault::from("whole original diagnostic close refusal");fault.retained_progress=receipt;semio_framework_job::OriginalTurnPrimary::from(fault)}else{ValueError::literal(ValueRefusalKind::InvariantViolated,"whole original value close refusal").with_retained_progress(receipt).into()});
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant(),|cx|semio_framework_job::close_original_retained_turn(cx,RetirementDemand{release_bytes:released,depth:1,..Default::default()},|_|{drop(original.take());Err(primary.take().unwrap())})));let failure=result.unwrap_err();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,released));assert_eq!(failure.primary.retained_progress(),receipt);assert_eq!(caller.receipt(),receipt);assert!(failure.receipt_refusal.is_none());if diagnostic{assert!(failure.primary_fault().is_some())}else{assert!(failure.primary_value().is_some())}let mut failure_owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(failure).map_err(|(error,_)|error).unwrap();for _ in 0..10000{if failure_owner.terminal_is_empty(){break}let demand=failure_owner.next_demand(grant().maximum_copy_bytes).unwrap();caller.turn(grant(),|cx|semio_framework_job::close_original_retained_step(cx,demand,|loan|failure_owner.step(loan))).unwrap();}assert!(failure_owner.terminal_is_empty());close(&mut caller,&mut decoder);caller.retire(grant());}
 eprintln!("[DEBUG] full original diagnostic and value primaries survive the actual close release receipt");
}
